	image = "shertul_fortress_lore1.png",
	lore = function() return _t[[You see here a mural showing a dark and tortured world. Large, god-like figures with powerful auras fight each other, and the earth is torn beneath their feet.
There is some text underneath ]]..(not game.player:attr("speaks_shertul") and _t[[which you do not understand: #{italic}#'Sho ch'zun Eyal mor donuth, ik ranaheli donoth trun ze.'#{normal}#]] or _t[[#{italic}#'In the beginning the world was dark, and the petty gods fought over their broken lands.'#{normal}#]])
	end,
}

newLore{
	id = "shertul-fortress-2",
	category = "sher'tul",
	name = _t"second mural painting", always_pop = true,
	image = "shertul_fortress_lore2.png",
	lore = function() return _t[[In this picture a huge god with glowing eyes towers above the land, and in his right hand he holds high the sun. The other gods are running from him, wincing from the light.
There is some text underneath ]]..(not game.player:attr("speaks_shertul") and _t[[which you do not understand: #{italic}#'Fa AMAKTHEL tabak, ik koru bazan tro yu, ik ranaheli tobol don schek ruun. Ik blana dem Soli as banafel ik goriz uf Eyal ik blod, "Tro fasa goru domus asam, ik goru domit tro Eyal."'#{normal}#]] or _t[[[[SOURCE_MATCH_1]]]])
	end,
}

newLore{
	id = "shertul-fortress-3",
	category = "sher'tul",
	name = _t"third mural painting", always_pop = true,
	image = "shertul_fortress_lore3.png",
	lore = function() return _t[[This picture shows the huge god holding some smaller figures in his hands and pointing out at the lands beyond. You imagine these figures must be the Sher'Tul.
There is some text beneath ]]..(not game.player:attr("speaks_shertul") and _t[[which you do not understand: #{italic}#'Ik AMAKTHEL cosio SHER'TUL, ik baladath peris furko masa bren doth benna zi, ik blod is "Fen makel ath goru domus ik denz tro ala fron."'#{normal}#]] or _t[[#{italic}#'And AMAKTHEL made the SHER'TUL, and gave unto us the powers to achieve all that we set our will to, and said to us "Go forth to where the light touches and take all for your own."'#{normal}#]])
	end,
}

